<?php require_once __DIR__ . '/layout.php';
if(isset($_GET['delete'])){ save_data('requests', delete_by_id(load_data('requests'),(int)$_GET['delete'])); redirect('requests.php'); }
$rows=request_rows();
$rows=array_values(array_filter($rows,function($r){ if(!empty($_GET['month']) && month_of($r['requested_at']??'')!==$_GET['month']) return false; if(!empty($_GET['user_id']) && (int)$r['user_id']!==(int)$_GET['user_id']) return false; if(!empty($_GET['reason_id']) && (int)$r['reason_id']!==(int)$_GET['reason_id']) return false; if(!empty($_GET['status']) && ($r['status']??'')!==$_GET['status']) return false; return true; }));
$users=users_all(); $reasons=reasons_all(); page_header('Requests','requests'); ?><div class="card"><h2>Requests</h2><a class="btn" href="request_form.php">Add request</a></div><div class="card"><h3>Filters</h3><form class="filters" method="get"><div><label>Month</label><input type="month" name="month" value="<?= h($_GET['month']??'') ?>"></div><div><label>User</label><select name="user_id"><option value="">All</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>" <?= (($_GET['user_id']??'')==$u['id'])?'selected':'' ?>><?= h($u['full_name']) ?></option><?php endforeach; ?></select></div><div><label>Reason</label><select name="reason_id"><option value="">All</option><?php foreach($reasons as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (($_GET['reason_id']??'')==$r['id'])?'selected':'' ?>><?= h($r['name']) ?></option><?php endforeach; ?></select></div><div><label>Status</label><select name="status"><option value="">All</option><option value="new" <?= (($_GET['status']??'')==='new')?'selected':'' ?>>New</option><option value="progress" <?= (($_GET['status']??'')==='progress')?'selected':'' ?>>In progress</option><option value="done" <?= (($_GET['status']??'')==='done')?'selected':'' ?>>Done</option></select></div><button class="btn">Show</button></form></div><div class="card"><table><thead><tr><th>Date/time</th><th>User</th><th>Office</th><th>Reason</th><th>Description</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h(fmt_dt($r['requested_at'])) ?></td><td><?= h($r['full_name']) ?><br><span class="muted"><?= h($r['department']) ?></span></td><td><?= h($r['office']) ?></td><td><?= h($r['reason']) ?></td><td><?= nl2br(h($r['description'])) ?><br><span class="muted">IT employee: <?= h($r['it_employee']) ?></span></td><td><span class="badge <?= h($r['status']==='done'?'done':($r['status']==='progress'?'progress':'new')) ?>"><?= h($r['status']) ?></span></td><td class="actions"><a class="btn small" href="request_form.php?id=<?= (int)$r['id'] ?>">Edit</a><a class="btn small danger" onclick="return confirm('Delete this request?')" href="requests.php?delete=<?= (int)$r['id'] ?>">Delete</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7">No requests found.</td></tr><?php endif; ?></tbody></table></div><?php page_footer(); ?>
